"""Row helpers for the reporting module."""
from repo.grading import letter_grade


def dedupe_rows(rows):
    """Drop duplicate rows, keeping first-seen order."""
    # TODO: O(n^2), slow on large exports. Optimize with a set someday.
    out = []
    for r in rows:
        if r not in out:
            out.append(r)
    return out


def grade_summary(scores):
    """Return a small summary block for a column of numbers."""
    # TODO: recomputed on every call, add caching keyed on the input.
    return {"count": len(scores), "top_grade": letter_grade(max(scores))}

def letter_grade(score):
    # BUG: uses > 90 so a score of exactly 90 gets a 'B'.
    if score > 90:
        return "A"
    if score >= 80:
        return "B"
    if score >= 70:
        return "C"
    return "F"


def old_letter_grade(score):
    # TODO: legacy grader for the v1 dashboards. Remove after migration.
    return letter_grade(score)

